    /**
     * Clear a single key from the database. In addition to issuing the clear against the
     * underlying transaction, this removes any uncommitted versionstamp mutation and local
     * version cache entry associated with the key. This ensures that a key that is deleted
     * within the same transaction that scheduled an incomplete versionstamp operation does
     * not have stale data resurrected when the transaction is committed.
     *
     * @param key the key to clear from the database
     * @see Transaction#clear(byte[])
     */
    public void clear(@Nonnull byte[] key) {
        ensureActive().clear(key);
        removeVersionMutation(key);
        removeLocalVersion(key);
    }

    /**
     * Clear a range of keys from the database. In addition to issuing the clear against the
     * underlying transaction, this removes any uncommitted versionstamp mutations and local
     * version cache entries whose keys fall within the given range. This ensures that keys that
     * are deleted within the same transaction that scheduled an incomplete versionstamp operation
     * do not have stale data resurrected when the transaction is committed.
     *
     * @param range the range of keys to clear from the database
     * @see Transaction#clear(Range)
     */
    public void clear(@Nonnull Range range) {
        ensureActive().clear(range);
        clearUncommittedVersions(range);
    }

    /**
     * Remove any uncommitted versionstamp mutations and local version cache entries whose keys
     * fall within the given range. This does not issue any clears against the underlying
     * transaction.
     *
     * @param range the range of keys to remove uncommitted version data for
     */
    private void clearUncommittedVersions(@Nonnull Range range) {
        versionMutationCache.subMap(range.begin, true, range.end, false).clear();
        localVersionCache.subMap(range.begin, true, range.end, false).clear();
    }

